require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_login();$id=(int)($_GET['id']??0);$st=$conn->prepare('SELECT * FROM cars WHERE id=?');$st->bind_param('i',$id);$st->execute();$car=$st->get_result()->fetch_assoc();if(!$car){set_flash('error','Car not found.');redirect_to('backend/cars/list.php');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$car_name=trim($_POST['car_name']??'');$plateRaw=strtoupper(trim($_POST['plate_number']??''));$plate=$plateRaw===''?null:$plateRaw;$chassis=strtoupper(trim($_POST['chassis_number']??''));$price=(float)($_POST['purchase_price']??0);$date=$_POST['purchase_date']??'';if($car_name===''||$chassis===''||$price<=0||$date===''){$error='Please fill all required fields correctly.';}else{$up=$conn->prepare('UPDATE cars SET car_name=?, plate_number=?, chassis_number=?, purchase_price=?, purchase_date=? WHERE id=?');$up->bind_param('sssdsi',$car_name,$plate,$chassis,$price,$date,$id);if($up->execute()){$stock_type=$_POST['stock_type']??'OWNED';$make=trim($_POST['make']??'');$model=trim($_POST['model']??'');$year=(int)($_POST['model_year']??0);$color=trim($_POST['color']??'');$mileage=(int)($_POST['mileage']??0);$transmission=trim($_POST['transmission']??'');$fuel=trim($_POST['fuel_type']??'');$engine=trim($_POST['engine_number']??'');$asking=(float)($_POST['asking_price']??0);$supplier=trim($_POST['supplier_name']??'');$supplierPhone=trim($_POST['supplier_phone']??'');$owner=trim($_POST['owner_name']??'');$ownerPhone=trim($_POST['owner_phone']??'');$yard=trim($_POST['yard_location']??'');$notes=trim($_POST['vehicle_notes']??'');$ex=$conn->prepare('UPDATE cars SET stock_type=?,make=?,model=?,model_year=NULLIF(?,0),color=?,mileage=NULLIF(?,0),transmission=?,fuel_type=?,engine_number=?,asking_price=NULLIF(?,0),supplier_name=?,supplier_phone=?,owner_name=?,owner_phone=?,yard_location=?,vehicle_notes=? WHERE id=?');$ex->bind_param('sssisisssdssssssi',$stock_type,$make,$model,$year,$color,$mileage,$transmission,$fuel,$engine,$asking,$supplier,$supplierPhone,$owner,$ownerPhone,$yard,$notes,$id);$ex->execute();require_once __DIR__.'/../includes/business_helpers.php';car_sales_audit($conn,'UPDATE','car',$id,'Updated vehicle record.',null,['car_name'=>$car_name,'plate_number'=>$plate,'chassis_number'=>$chassis,'purchase_price'=>$price,'purchase_date'=>$date]);set_flash('success','Car updated successfully.');redirect_to('backend/cars/view.php?id='.$id);}else{$error='Could not update car. The chassis number, or a supplied plate number, may already exist.';}}}
